  const [petForm, setPetForm] = useState({ name: "", type: "gato" as "gato" | "perro" | "otro", avatar: "🐱" });

  const [qrOpen, setQrOpen] = useState(false);
  const [addOpen, setAddOpen] = useState(false);
  const [form, setForm] = useState({ name: "", amount: "", cat: "comida", shared: false, who: "yo" as "yo" | "pareja", petId: "" });
  const [filter, setFilter] = useState<string | null>(null);
  const [joinCode, setJoinCode] = useState("");
  const [preset, setPreset] = useState<Preset | null>(null);
  const [presetAmount, setPresetAmount] = useState("");
  const [presetWho, setPresetWho] = useState<"yo" | "pareja">("yo");
  const [presets, setPresets] = useState<Preset[]>(DEFAULT_PRESETS);
  const [manage, setManage] = useState(false);
  const [presetEdit, setPresetEdit] = useState<PresetDraft | null>(null);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || "";
    const lang = navigator.language || "";
    if (tz.includes("Argentina") || lang.includes("AR")) setCurrency("ARS");
    else if (tz.includes("Bogota") || tz.includes("Colombia") || lang.includes("CO")) setCurrency("COP");
    else if (lang.startsWith("es") && !lang.includes("MX") && !lang.includes("AR") && !lang.includes("CO")) setCurrency("EUR");

    const savedCurrency = localStorage.getItem("gastos-currency") as Currency;
    if (savedCurrency) setCurrency(savedCurrency);

    const raw = localStorage.getItem("gastos");
    if (raw) setExpenses(JSON.parse(raw));

    const savedMyProf = localStorage.getItem("gastos-my-profile");
    if (savedMyProf) setMyProfile(JSON.parse(savedMyProf));

    const savedPartnerProf = localStorage.getItem("gastos-partner-profile");
    if (savedPartnerProf) setPartnerProfile(JSON.parse(savedPartnerProf));

    const savedSplit = localStorage.getItem("gastos-split-half");
    if (savedSplit !== null) setSplitHalf(savedSplit === "true");

    const savedPets = localStorage.getItem("gastos-pets");
    if (savedPets) {
      try { setPets(JSON.parse(savedPets)); } catch {}
    }

    let c = localStorage.getItem("gastos-code");
    if (!c) { c = Math.random().toString(36).slice(2, 8).toUpperCase(); localStorage.setItem("gastos-code", c); }
    setCode(c);
    setPartner(localStorage.getItem("gastos-partner"));
    
    const rawPresets = localStorage.getItem("gastos-presets");
    if (rawPresets) {
      try {
        const parsed = JSON.parse(rawPresets) as Preset[];
        if (Array.isArray(parsed)) setPresets(parsed.filter((p) => p && p.id && p.name && ICONS[p.icon]));
      } catch {}
    }
    setReady(true);
  }, []);

  useEffect(() => { if (ready) localStorage.setItem("gastos", JSON.stringify(expenses)); }, [expenses, ready]);
  useEffect(() => { if (ready) localStorage.setItem("gastos-presets", JSON.stringify(presets)); }, [presets, ready]);
  useEffect(() => { if (ready) localStorage.setItem("gastos-currency", currency); }, [currency, ready]);
  useEffect(() => { if (ready) localStorage.setItem("gastos-my-profile", JSON.stringify(myProfile)); }, [myProfile, ready]);
  useEffect(() => { if (ready) localStorage.setItem("gastos-partner-profile", JSON.stringify(partnerProfile)); }, [partnerProfile, ready]);
  useEffect(() => { if (ready) localStorage.setItem("gastos-split-half", String(splitHalf)); }, [splitHalf, ready]);
  useEffect(() => { if (ready) localStorage.setItem("gastos-pets", JSON.stringify(pets)); }, [pets, ready]);

  const add = (e: Omit<Expense, "id" | "date">) =>
    setExpenses((p) => [{ ...e, id: crypto.randomUUID(), date: new Date().toISOString() }, ...p]);

  const scoped = mode === "individual" 
    ? expenses.filter((e) => !e.shared && !e.petId)
    : mode === "pareja"
    ? expenses.filter((e) => e.shared && !e.petId)
    : expenses.filter((e) => e.petId);

  const visible = useMemo(() => scoped.filter((e) => !filter || e.cat === filter), [scoped, filter]);

  const total = scoped.reduce((s, e) => s + e.amount, 0);
  const byCat = CATS.map((c) => ({ ...c, total: scoped.filter((e) => e.cat === c.id).reduce((s, e) => s + e.amount, 0) }))
    .filter((c) => c.total > 0).sort((a, b) => b.total - a.total);
  
  const mine = scoped.filter((e) => e.who === "yo").reduce((s, e) => s + e.amount, 0);
  const theirs = total - mine;
  
